-- Bước chuẩn bị: nạp 309 dòng của before; chưa làm sạch.
-- Các giá trị được lấy trực tiếp từ CSV, không lấy kết quả Python đã xử lý.
-- Ô rỗng được nạp thành SQL NULL; giữ khoảng trắng trong chuỗi không rỗng.
-- source_csv_line tính cả dòng tiêu đề (hồ sơ đầu tiên ở dòng 2).
-- SHA-256 before: d14cfc3e65d5b7eb772bec919bef749de338ea7f63a509ee66c830dd3293e8c5
USE [HeartFailure_DoAn];
GO
SET NOCOUNT ON;
SET XACT_ABORT ON;

IF OBJECT_ID(N'dbo.heart_before_raw', N'U') IS NULL
BEGIN
    BEGIN TRY
        BEGIN TRANSACTION;
        CREATE TABLE dbo.heart_before_raw (
            source_csv_line INT NOT NULL PRIMARY KEY,
            [age] NVARCHAR(100) NULL,
            [anaemia] NVARCHAR(100) NULL,
            [creatinine_phosphokinase] NVARCHAR(100) NULL,
            [diabetes] NVARCHAR(100) NULL,
            [ejection_fraction] NVARCHAR(100) NULL,
            [high_blood_pressure] NVARCHAR(100) NULL,
            [platelets] NVARCHAR(100) NULL,
            [serum_creatinine] NVARCHAR(100) NULL,
            [serum_sodium] NVARCHAR(100) NULL,
            [sex] NVARCHAR(100) NULL,
            [smoking] NVARCHAR(100) NULL,
            [time] NVARCHAR(100) NULL,
            [DEATH_EVENT] NVARCHAR(100) NULL
        );

        IF (SELECT COUNT(*) FROM dbo.heart_before_raw) <> 309
            THROW 51000, N'Số dòng nhập không khớp 309; giao dịch được hủy.', 1;
        COMMIT TRANSACTION;
        PRINT N'Đã nhập 309 dòng vào dbo.heart_before_raw.';
    END TRY
    BEGIN CATCH
        IF @@TRANCOUNT > 0 ROLLBACK TRANSACTION;
        THROW;
    END CATCH;
END
ELSE
BEGIN
    PRINT N'Bảng đã tồn tại: giữ nguyên dữ liệu, không nhập thêm hoặc ghi đè.';
END;
GO

-- Kết quả 1: kiểm tra số dòng, số dòng trống và số dòng có dữ liệu.
SELECT
    COUNT(*) AS TongSoDong,
    SUM(CASE WHEN NULLIF(LTRIM(RTRIM([age])), N'') IS NULL AND NULLIF(LTRIM(RTRIM([anaemia])), N'') IS NULL AND NULLIF(LTRIM(RTRIM([creatinine_phosphokinase])), N'') IS NULL AND NULLIF(LTRIM(RTRIM([diabetes])), N'') IS NULL AND NULLIF(LTRIM(RTRIM([ejection_fraction])), N'') IS NULL AND NULLIF(LTRIM(RTRIM([high_blood_pressure])), N'') IS NULL AND NULLIF(LTRIM(RTRIM([platelets])), N'') IS NULL AND NULLIF(LTRIM(RTRIM([serum_creatinine])), N'') IS NULL AND NULLIF(LTRIM(RTRIM([serum_sodium])), N'') IS NULL AND NULLIF(LTRIM(RTRIM([sex])), N'') IS NULL AND NULLIF(LTRIM(RTRIM([smoking])), N'') IS NULL AND NULLIF(LTRIM(RTRIM([time])), N'') IS NULL AND NULLIF(LTRIM(RTRIM([DEATH_EVENT])), N'') IS NULL THEN 1 ELSE 0 END) AS DongTrong,
    SUM(CASE WHEN NOT (NULLIF(LTRIM(RTRIM([age])), N'') IS NULL AND NULLIF(LTRIM(RTRIM([anaemia])), N'') IS NULL AND NULLIF(LTRIM(RTRIM([creatinine_phosphokinase])), N'') IS NULL AND NULLIF(LTRIM(RTRIM([diabetes])), N'') IS NULL AND NULLIF(LTRIM(RTRIM([ejection_fraction])), N'') IS NULL AND NULLIF(LTRIM(RTRIM([high_blood_pressure])), N'') IS NULL AND NULLIF(LTRIM(RTRIM([platelets])), N'') IS NULL AND NULLIF(LTRIM(RTRIM([serum_creatinine])), N'') IS NULL AND NULLIF(LTRIM(RTRIM([serum_sodium])), N'') IS NULL AND NULLIF(LTRIM(RTRIM([sex])), N'') IS NULL AND NULLIF(LTRIM(RTRIM([smoking])), N'') IS NULL AND NULLIF(LTRIM(RTRIM([time])), N'') IS NULL AND NULLIF(LTRIM(RTRIM([DEATH_EVENT])), N'') IS NULL) THEN 1 ELSE 0 END) AS DongCoDuLieu
FROM dbo.heart_before_raw;

-- Kết quả 2: xem 10 dòng đầu, gồm cả lỗi trong sex ở dòng CSV số 10.
SELECT TOP (10) *
FROM dbo.heart_before_raw
ORDER BY source_csv_line;

-- Kết quả 3: chứng minh vẫn giữ được chuỗi tuổi sai kiểu.
SELECT source_csv_line, age
FROM dbo.heart_before_raw
WHERE age = N'Invalid_Age';

-- Kết quả 4: kiểm tra 5 dòng trống cuối file vẫn được nhập đầy đủ.
SELECT *
FROM dbo.heart_before_raw
WHERE NULLIF(LTRIM(RTRIM([age])), N'') IS NULL AND NULLIF(LTRIM(RTRIM([anaemia])), N'') IS NULL AND NULLIF(LTRIM(RTRIM([creatinine_phosphokinase])), N'') IS NULL AND NULLIF(LTRIM(RTRIM([diabetes])), N'') IS NULL AND NULLIF(LTRIM(RTRIM([ejection_fraction])), N'') IS NULL AND NULLIF(LTRIM(RTRIM([high_blood_pressure])), N'') IS NULL AND NULLIF(LTRIM(RTRIM([platelets])), N'') IS NULL AND NULLIF(LTRIM(RTRIM([serum_creatinine])), N'') IS NULL AND NULLIF(LTRIM(RTRIM([serum_sodium])), N'') IS NULL AND NULLIF(LTRIM(RTRIM([sex])), N'') IS NULL AND NULLIF(LTRIM(RTRIM([smoking])), N'') IS NULL AND NULLIF(LTRIM(RTRIM([time])), N'') IS NULL AND NULLIF(LTRIM(RTRIM([DEATH_EVENT])), N'') IS NULL
ORDER BY source_csv_line;
